# French versions of the 6 guides (Marketing & croissance, 25/11/2026): same content as the English, written for French rappers
FR = {
 'lip-sync-video-editor': dict(slug='editeur-video-playback', crumb='Éditeur vidéo de playback', cta='Monter ma vidéo, gratuit',
  title='Éditeur vidéo de playback : tes prises sur le rythme | Stalak',
  desc='Éditeur vidéo de playback gratuit pour rappeurs et chanteurs : ton son et quelques prises, Stalak passe de l’une à l’autre sur le rythme, lèvres synchro. Sans appli ni compte.',
  h1='Un éditeur vidéo de playback qui fait le montage pour toi',
  lead='Stalak est un éditeur vidéo de playback gratuit qui marche dans ton navigateur. Importe ton son et quelques vidéos où tu le performes : Stalak passe d’une prise à l’autre sur le rythme, en gardant ta bouche synchro avec le son. Sans téléchargement, sans compte, prêt pour TikTok, Reels et Shorts.',
  why=('Ce qui change', ['Il monte tes <strong>vraies prises</strong>. Pas de visage IA, pas de fausse bouche.', 'Les coupes tombent sur le rythme : phrase par phrase, sur tes lignes et tes rimes, ou à chaque mesure. Tu choisis.', 'Paroles à l’écran, en phrases entières en gratuit, mot par mot ou karaoké avec Pro.', 'Tout se passe sur ton appareil : tes vidéos restent à toi.']),
  deep=('Ce que Stalak fait de tes prises', ['Chaque prise a été filmée avec ton son qui tournait, donc son audio correspond à un moment du morceau. Stalak écoute chaque prise, retrouve ce moment et la cale sur ton son. Ensuite, quelle que soit la prise à l’écran, ta bouche suit l’audio.', 'Puis il prévoit les coupes. Stalak trouve le rythme et les mesures de ton son et choisit où changer de prise. <strong>Auto</strong> suit la musique phrase par phrase. <strong>Sur les mots</strong> coupe au début de chaque ligne et sur la rime à la fin, une fois tes paroles calées. <strong>Par mesure</strong> donne chaque mesure à une prise différente, à tour de rôle. Le réglage <strong>Rythme</strong> va de Posé (plans longs, peu de coupes) à Nerveux (coupes rapides, jusqu’à chaque temps).', 'Tu gardes la main. Touche <strong>Régénérer</strong> pour un nouveau montage. Si un plan est parfait, touche <strong>Garder ce plan</strong> : il reste en place pendant que tu régénères le reste ; <strong>Changer de prise</strong> en met une autre à sa place.', 'Si les coupes semblent à côté du rythme, ouvre « Les coupes ne tombent pas en rythme ? » sous ton son, touche <strong>TAP</strong> en suivant la musique, en partant d’un temps fort, et valide. Stalak affine tes tapes sur le son lui-même, puis joue des bips pour que tu vérifies.', 'Quand c’est bon, exporte. La vidéo est fabriquée sur ton appareil, en pleine qualité à partir de tes fichiers d’origine, prête pour TikTok, Reels et Shorts.']),
  tips=('Conseils pour un playback propre', ['Fais tourner le son à voix haute pendant que tu filmes, pour que chaque prise suive le même audio.', 'Filme 3 ou 4 prises à des endroits différents : gros plan, plan large, autre mur ou autre lumière.', 'Lance chaque prise une ou deux secondes avant le passage que tu veux poster.']),
  faq=[('C’est quoi un éditeur vidéo de playback ?', 'Un éditeur qui garde ta performance calée sur le son pendant qu’il passe d’un plan à l’autre. Stalak fait le calage et les coupes pour toi : tu apportes juste tes prises.')]),
 'music-video-maker-for-rappers': dict(slug='faire-un-clip-de-rap', crumb='Faire un clip de rap', cta='Monter mon snippet, gratuit',
  title='Faire un clip de rap avec ton téléphone, sur le rythme | Stalak',
  desc='Fais un clip de rap avec quelques prises au téléphone. Stalak coupe sur le rythme, ajoute tes paroles et exporte en 9:16 pour TikTok, ou en clip 16:9 pour YouTube. Gratuit pour commencer.',
  h1='Un outil de clip fait par un rappeur, pour les rappeurs',
  lead='Stalak transforme quelques prises filmées au téléphone en clip de rap coupé sur le rythme. Importe ton son, ajoute tes prises, et exporte un snippet vertical pour TikTok, Reels ou Shorts, ou tout le morceau en clip 16:9 pour YouTube avec Stalak Pro. Ça marche dans ton navigateur, gratuit pour commencer.',
  why=('Fait pour la façon dont les rappeurs postent', ['Poste le même son tous les jours sans tout remonter : Creator Plus fait des packs de 5 à 30 vidéos, chacune coupée différemment.', 'Le mode Clip 16:9 pour tout le morceau, avec des effets comme flash, zoom, secousse et ralenti (Pro).', 'Paroles automatiques : Stalak écrit et cale tes phases à partir de ta voix (Pro).', 'Créé par 99Sayso, rappeur indépendant qui a codé Stalak pour ses propres vidéos.']),
  deep=('Prépare un tournage qui se monte bien', ['Pas besoin d’équipe, mais le montage ne sera jamais meilleur que tes prises. Choisis deux ou trois endroits faciles à faire dans l’après-midi : ta chambre, une cage d’escalier, un toit, un parking la nuit. Garde la même tenue, pour que les coupes donnent un clip et pas une playlist.', 'À chaque endroit, filme tout le passage que tu vas poster, ou tout le son pour YouTube, avec le morceau qui tourne sur une enceinte. Fais une prise serrée sur ton visage et une plus large, pour que le montage alterne entre énergie et décor. Pas besoin de lancer les prises au même moment : Stalak cale chacune sur le son tout seul.', 'Pour TikTok, Reels et Shorts, garde un snippet court et vertical. Pour YouTube, le mode Clip de Stalak Pro monte tout le morceau en 16:9, et tu peux mettre des effets sur les coupes : flash, zoom, secousse et ralenti.', 'Une fois le montage fait, ne t’arrête pas à une vidéo. Avec Creator Plus, le générateur de packs fait 5 à 30 vidéos avec les mêmes prises, chacune coupée différemment : ton son peut tourner toute la semaine sans faire repost.', 'La démo au-dessus, c’est du vrai : trois prises de 99Sayso, dans un jardin, un grenier et devant des montagnes, montées par Stalak avec une coupe par mesure.']),
  tips=('Conseils pour un clip de rap au téléphone', ['Tourne à plusieurs endroits avec la même tenue : les coupes font un vrai clip.', 'Éclaire bien ton visage ; les coupes sont plus nettes quand chaque prise est claire.', 'Pour un clip complet, filme tout le son à chaque prise.']),
  faq=[('Je peux faire un clip complet, pas seulement un snippet ?', 'Oui. Avec Stalak Pro, le mode Clip 16:9 monte tout le morceau pour YouTube, avec des effets.')]),
 'rap-snippet-video': dict(slug='snippet-rap', crumb='Snippet de rap', cta='Monter mon snippet, gratuit',
  title='Snippet de rap : tes prises coupées sur le rythme | Stalak',
  desc='Un snippet à teaser ? Importe ton son et quelques prises où tu rappes : Stalak les coupe sur le rythme, paroles à l’écran. Gratuit, dans ton navigateur.',
  h1='Fais de tes prises un snippet, coupé sur le rythme',
  lead='Un snippet, ce sont les 10 à 30 secondes que tu postes avant la sortie d’un son. Avec Stalak, tu choisis ce passage, tu ajoutes quelques prises où tu le rappes, et tu obtiens un snippet coupé sur le rythme avec tes paroles à l’écran. Gratuit, dans ton navigateur, prêt à poster.',
  why=('Pensé pour la promo d’un son', ['Choisis le passage exact du son à poster, à la mesure près.', 'Paroles à l’écran, pour qu’on capte les phases sans le son.', 'Packs Creator Plus : 5 à 30 montages différents du même snippet, pour poster chaque jour de ta promo.', 'Vertical 9:16, prêt pour TikTok, Reels et Shorts.']),
  deep=('Une semaine de snippets avec une seule séance', ['Pousser un son, c’est le poster encore et encore jusqu’à ce qu’il accroche. Filmer du nouveau tous les jours t’épuise : filme une fois et monte plusieurs fois.', 'Le premier jour, c’est le tournage : trois ou quatre prises du snippet, à des endroits différents, avec le son qui tourne. À la première étape de Stalak, choisis le passage à poster, à la mesure près. Commence sur le refrain, ou sur la phase qu’on va citer.', 'Puis laisse Stalak faire le premier montage. Une fois tes paroles calées, <strong>Sur les mots</strong> coupe au début de chaque ligne et sur la rime : les changements tombent sur tes punchlines. Garde aussi les paroles à l’écran, pour qu’on capte les phases sans le son.', 'Les jours suivants, touche <strong>Régénérer</strong> pour un nouveau montage, ou change le rythme : Nerveux pour les jours de hype, Posé quand le passage est plus calme. Avec Creator Plus, le générateur de packs fait toute la semaine d’un coup : 5 à 30 vidéos avec les mêmes prises, chacune coupée différemment.', 'Poste-en une par jour et regarde quelle version les gens revoient et partagent. Quand un type de montage marche, garde-le pour la vidéo du jour de sortie.']),
  tips=('Conseils pour un snippet qu’on revoit', ['Commence sur le refrain ou la phase la plus forte : les 2 premières secondes décident de tout.', 'Fais court ; 10 à 20 secondes suffisent souvent.', 'Poste un montage différent chaque jour plutôt que deux fois la même vidéo.']),
  faq=[('Combien de temps doit durer un snippet de rap ?', 'Il n’y a pas de règle, mais les snippets courts qui commencent sur la phase la plus forte sont les plus faciles à revoir. Stalak te laisse choisir n’importe quel passage du son, à la mesure près.')]),
 'lip-sync-videos-for-singers': dict(slug='videos-pour-chanteurs', crumb='Vidéos pour chanteurs', cta='Monter ma vidéo, gratuit',
  title='Vidéos de chant pour chanteurs : plusieurs prises montées | Stalak',
  desc='Chanteur ou chanteuse ? Filme quelques prises de ton son, Stalak en fait une vidéo de performance coupée sur le rythme, paroles à l’écran. Gratuit, sans appli ni compte.',
  h1='Des vidéos de performance pour chanteurs, montées pour toi',
  lead='Stalak monte quelques prises où tu chantes en une seule vidéo de performance. Importe ton son et tes prises : Stalak passe de l’une à l’autre sur le rythme ou sur les paroles, garde chaque prise synchro et ajoute tes paroles à l’écran. Ça marche pour les reprises et tes propres sons, gratuit dans ton navigateur.',
  why=('Ce que les chanteurs y gagnent', ['Coupes sur tes lignes et tes rimes, ou à chaque mesure, pour les sons lents qui demandent des plans longs.', 'Paroles karaoké et mot par mot avec Pro : les mots suivent ta voix.', 'Des filtres comme Pellicule 35 mm, Givre et Noir et blanc, en gratuit.', 'Une vidéo 16:9 de tout le morceau pour YouTube avec Pro.']),
  deep=('Filmer une performance qui tient', ['Le chant montre tout : les respirations, les notes tenues, la ligne que tu pousses exprès. Une coupe au mauvais endroit peut casser ça, alors Stalak te laisse choisir à quelle fréquence il coupe.', 'Pour les ballades et les sons lents, choisis <strong>Par mesure</strong> ou le rythme <strong>Posé</strong> : les plans durent plus et le montage respire avec le son. Pour un son plus rapide, <strong>Auto</strong> avec le rythme Normal ou Nerveux garde du mouvement. Une fois tes paroles calées, <strong>Sur les mots</strong> change de prise au début de chaque ligne et sur la rime, ce qui tombe souvent juste en chant.', 'Chaque prise est calée sur le même audio : ta bouche reste sur les mots après chaque coupe, notes tenues comprises. Chante à pleine voix pendant que tu filmes : un playback chuchoté se voit à l’image.', 'Varie les cadrages : un gros plan pour les lignes qui font mal, un plan plus large qui montre la pièce ou la tenue. Éclaire ton visage de face (une fenêtre suffit) pour que chaque prise reste nette.', 'Avec Stalak Pro, les paroles peuvent suivre ta voix mot par mot, ou s’allumer comme au karaoké, dans toutes les tailles. Pour une reprise, vérifie que tu as le droit de poster le son sur la plateforme.']),
  tips=('Conseils pour une vidéo de chant', ['Pour les ballades, choisis « Par mesure » ou le rythme Posé plutôt que des coupes rapides. Pour couper sur les lignes, cale d’abord tes paroles.', 'Mélange gros plans et plans larges pour montrer l’émotion et le décor.', 'Pour les reprises, ne poste que des sons que tu as le droit d’utiliser sur la plateforme.']),
  faq=[('Ça marche pour les sons lents ?', 'Oui. Choisis « Par mesure » ou le rythme Posé pour des plans plus longs : le montage respire avec le son.')]),
 'how-to-make-a-lip-sync-video': dict(slug='comment-faire-une-video-playback', crumb='Faire une vidéo playback', cta='Monter ma vidéo, gratuit',
  title='Comment faire une vidéo playback en 4 étapes (gratuit) | Stalak',
  desc='Comment faire une vidéo playback pour TikTok, Reels ou Shorts : importe ton son, ajoute quelques prises et tes paroles, Stalak les coupe sur le rythme. Guide gratuit.',
  h1='Comment faire une vidéo playback en 4 étapes',
  lead='Pour faire une vidéo playback, filme quelques prises où tu performes le son, puis cale-les sur l’audio et passe de l’une à l’autre sur le rythme. Stalak fait le calage et les coupes pour toi : importe le son, ajoute tes prises, exporte. C’est gratuit et ça marche dans ton navigateur.',
  why=('Les 4 étapes', ['<strong>1. Importe ton son</strong>, ou le passage que tu veux poster.', '<strong>2. Ajoute tes prises</strong> : 2 vidéos ou plus où tu le performes, filmées avant ou directement avec la caméra de Stalak.', '<strong>3. Ajoute tes paroles</strong> si tu veux : colle-les et cale-les en tapant, ou laisse Stalak les écrire (Pro).', '<strong>4. Choisis comment ça coupe</strong> (Auto, Sur les mots ou Par mesure) et exporte pour TikTok, Reels ou Shorts.']),
  deep=('Chaque étape en détail', ['<strong>Ton son.</strong> Stalak prend un fichier MP3, WAV ou M4A, ou une vidéo dont il utilise le son. Garde tout le morceau ou juste quelques mesures : fais glisser les poignées pour régler le début et la fin.', '<strong>Tes prises.</strong> Filme chaque prise avec le son qui tourne à voix haute, du début à la fin du passage. Deux prises suffisent ; trois ou quatre rendent mieux, à des endroits différents. Si tu filmes directement dans Stalak, la caméra joue le son pour toi pendant que tu enregistres.', '<strong>Tes paroles (au choix).</strong> Colle une ligne par rangée, puis cale-les en tapant en rythme avec le son. En gratuit, elles s’affichent en phrases entières ; Stalak Pro ajoute le mot par mot et le karaoké, et peut les écrire et les caler pour toi.', '<strong>Le montage.</strong> Stalak fait tout de suite un premier montage. Essaie <strong>Régénérer</strong>, change le rythme, ou touche <strong>Garder ce plan</strong> sur les plans que tu aimes. Si les coupes semblent à côté, ouvre « Les coupes ne tombent pas en rythme ? » et tape le tempo.', '<strong>L’export.</strong> Touche Exporter : la vidéo est fabriquée sur ton appareil, en pleine qualité à partir de tes fichiers d’origine. Plus la vidéo est longue, plus ça prend de temps : un clip entier prend quelques minutes.']),
  tips=('Conseils de tournage', ['Fais tourner le son à voix haute pendant chaque prise.', 'Filme à la verticale pour TikTok, Reels et Shorts.', 'Fais au moins 3 prises sous des angles différents ; plus de prises, plus de variété dans les coupes.']),
  faq=[('Il faut combien de prises ?', 'Au moins 2. Trois ou quatre prises sous des angles différents donnent les plus belles coupes.'), ('Je peux filmer directement dans le navigateur ?', 'Oui. Stalak a une caméra intégrée : tu peux filmer tes prises directement dans le navigateur.')]),
 'edit-video-to-the-beat': dict(slug='monter-une-video-sur-le-rythme', crumb='Monter sur le rythme', cta='Monter ma vidéo, gratuit',
  title='Monter plusieurs prises sur le rythme, automatiquement | Stalak',
  desc='Fini le montage image par image. Stalak trouve le rythme de ton son et coupe entre tes prises tout seul : sur le temps, sur tes lignes ou à chaque mesure. Gratuit.',
  h1='Monter plusieurs prises sur le rythme, automatiquement',
  lead='Stalak trouve le rythme de ton son et passe d’une prise à l’autre tout seul. Les coupes suivent la musique phrase par phrase, tombent sur tes lignes et tes rimes, ou changent de prise à chaque mesure ; chaque prise reste synchro avec l’audio. Pas de timeline, pas de montage image par image. Gratuit, dans ton navigateur.',
  why=('Ce que veut dire « automatique » ici', ['Stalak trouve le rythme de ton son et place les coupes pour toi. Pour couper sur les paroles, cale-les d’abord : en tapant, ou avec les paroles automatiques (Pro).', 'Chaque prise reste calée sur l’audio : le playback tient après chaque coupe.', 'Le résultat ne te plaît pas ? Choisis un autre rythme de coupe et obtiens un nouveau montage.', 'Creator Plus fait 5 à 30 montages différents du même son d’un coup.']),
  deep=('Comment Stalak trouve le rythme', ['Quand tu importes un son, Stalak écoute son pouls : les kicks, les snares, les accents qui reviennent. Il en tire le tempo, en battements par minute, et le début de chaque mesure. Chaque coupe se cale sur cette grille.', 'La plupart des sons sont lus tout de suite. Certains le perturbent : une longue intro sans batterie, un beat qui change en route, un son en half-time. Si les coupes ne tombent pas juste, ouvre « Les coupes ne tombent pas en rythme ? » sous le son, touche <strong>TAP</strong> à chaque temps pendant quelques mesures, en partant d’un temps fort, et valide. Stalak affine tes tapes sur le son lui-même, puis joue des bips sur la musique pour que tu vérifies.', 'Une fois la grille juste, le mode de coupe décide où les prises changent. <strong>Auto</strong> suit la musique phrase par phrase. <strong>Sur les mots</strong> coupe au début des lignes et sur les rimes, toujours sur un temps, une fois tes paroles calées. <strong>Par mesure</strong> change de prise à chaque mesure, à tour de rôle. Le rythme allonge ou resserre les plans, de Posé à Nerveux.', 'Où que tombe une coupe, chaque prise reste calée sur l’audio : le playback tient du premier au dernier plan.']),
  tips=('Conseils pour un montage sur le rythme', ['Sons rapides : essaie le rythme Nerveux (coupes rapides, jusqu’à chaque temps) et « Par mesure » ; garde celui qui te plaît.', 'Utilise des prises aux cadrages différents pour que chaque coupe se voie.', 'Garde le même son qui tourne pendant le tournage de chaque prise.']),
  faq=[('Il faut un logiciel de montage ?', 'Non. Tout se passe dans ton navigateur, sur iPhone, Android ou ordinateur. Rien à installer.')]),
}
